export const PAGINATION_FILES: readonly PatchedFile[] = [
  editedFile('api/src/routes/orders/index.get.ts', [
    hunk(
      9,
      [
        ctx('export default defineRoute(async (request) => {'),
        ctx('  const customer = await requireCustomer(request);'),
        del('  return listOrders(customer.id);'),
        add('  const { limit, cursor } = getQuery(request);'),
        add('  const pageSize = parsePageSize(limit);'),
        add('  if (pageSize === null) throw badRequest(`limit must be at most ${MAX_PAGE_SIZE}`);'),
        add('  const page = await listOrders(customer.id, { pageSize, cursor: decodeCursor(cursor) });'),
        add('  return { orders: page.orders, nextCursor: page.next === null ? null : encodeCursor(page.next) };'),
        ctx('});'),
      ],
      "import { requireCustomer } from '../../auth';",
    ),
  ]),
  createdFile('api/src/orders/pagination.ts', [
    'export const DEFAULT_PAGE_SIZE = 20;',
    'export const MAX_PAGE_SIZE = 100;',
    '',
    'export function parsePageSize(raw: unknown): number | null {',
    '  if (raw === undefined) return DEFAULT_PAGE_SIZE;',
    '  const size = Number(raw);',
    '  return Number.isInteger(size) && size > 0 && size <= MAX_PAGE_SIZE ? size : null;',
    '}',
    '',
    'export function encodeCursor(position: { placedAt: string; id: string }): string {',
    "  return Buffer.from(JSON.stringify(position)).toString('base64url');",
    '}',
    '',
    'export function decodeCursor(cursor: unknown): { placedAt: string; id: string } | null {',
    '  if (typeof cursor !== "string") return null;',
    '  try {',
    "    return JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));",
    '  } catch {',
    "    throw badRequest('the cursor is not valid');",
    '  }',
    '}',
  ]),
  createdFile(CHECK_PATH.pagination, [
    "import { describe, expect, it } from 'vitest';",
    "import { customerWithOrders, getOrders } from './support';",
    '',
    "describe('GET /api/orders', () => {",
    "  it('returns 20 orders by default and a cursor for the next page', async () => {",
    '    const customer = await customerWithOrders(250);',
    '    const page = await getOrders(customer, {});',
    '    expect(page.orders).toHaveLength(20);',
    '    expect(page.nextCursor).not.toBeNull();',
    '  });',
    '',
    "  it('refuses a limit above 100', async () => {",
    '    const customer = await customerWithOrders(3);',
    '    const response = await getOrders(customer, { limit: 101 }, { raw: true });',
    '    expect(response.status).toBe(400);',
    '  });',
    '});',
  ]),
];

